-- Creación de Dimensiones
CREATE TABLE dim_cliente (
    cliente_key SERIAL PRIMARY KEY,
    nombre VARCHAR(100),
    pais VARCHAR(50)
);

CREATE TABLE dim_producto (
    producto_key SERIAL PRIMARY KEY,
    categoria VARCHAR(50),
    precio_unitario NUMERIC(10,2)
);

-- Creación de Tabla de Hechos
CREATE TABLE fact_ventas (
    venta_id SERIAL PRIMARY KEY,
    cliente_key INT REFERENCES dim_cliente(cliente_key),
    producto_key INT REFERENCES dim_producto(producto_key),
    cantidad INT NOT NULL,
    monto_total NUMERIC(10,2) NOT NULL
);

-- Inserción de prueba y consulta analítica de estrella
INSERT INTO dim_cliente (nombre, pais) VALUES ('Alice', 'Espana'), ('Bob', 'Mexico');
INSERT INTO dim_producto (categoria, precio_unitario) VALUES ('Electronica', 150.00);
INSERT INTO fact_ventas (cliente_key, producto_key, cantidad, monto_total) VALUES (1, 1, 2, 300.00), (2, 1, 1, 150.00);

SELECT 
    c.pais,
    SUM(f.monto_total) AS total_ingresos
FROM fact_ventas f
JOIN dim_cliente c ON f.cliente_key = c.cliente_key
GROUP BY c.pais
ORDER BY total_ingresos DESC;
